import {defaults,sample,phases,markdown} from './brief.js';
const form=document.querySelector('form'),key='avytrix-brief-v1';let state=structuredClone(defaults),storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved==='object'){for(const k of Object.keys(defaults)){if(k!=='features'&&typeof saved[k]==='string')state[k]=saved[k];}if(Array.isArray(saved.features))state.features=saved.features.filter(x=>typeof x==='string');if(!['2','4','6','8'].includes(state.duration))state.duration='4';}}catch{storageOK=false;}
function setForm(){for(const [k,v]of Object.entries(state)){if(k==='features')form.querySelectorAll('[name=features]').forEach(el=>el.checked=v.includes(el.value));else form.elements[k].value=v;}render();}
function render(){const values={name:state.name||'Dự án tiếp theo của bạn',type:state.type,duration:state.duration+' tuần dự kiến',audience:state.audience||'Xác định nhóm người sử dụng chính.',goal:state.goal||'Mô tả vấn đề và kết quả bạn mong muốn đạt được.',success:state.success||'Bổ sung tiêu chí có thể kiểm chứng.',notes:state.notes||'Ghi lại các câu hỏi cần trao đổi với đối tác.'};for(const[k,v]of Object.entries(values))document.getElementById('p-'+k).textContent=v;const list=document.getElementById('p-features');list.replaceChildren(...(state.features.length?state.features:['Chưa chọn phạm vi.']).map(x=>{const li=document.createElement('li');li.textContent=x;return li;}));document.getElementById('timeline').replaceChildren(...phases(state.duration).map(x=>{const div=document.createElement('div'),span=document.createElement('span'),strong=document.createElement('strong');span.textContent=x.range;strong.textContent=x.name;div.append(span,strong);return div;}));document.getElementById('completion').textContent=[state.name,state.audience,state.goal,state.success].filter(x=>x.trim()).length+'/4 nội dung';}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}document.getElementById('save-status').textContent=storageOK?'Đã lưu trên thiết bị':'Không thể lưu nháp · hãy tải brief';}
form.addEventListener('input',()=>{const data=new FormData(form);state={...state,...Object.fromEntries([...data].filter(([k])=>k!=='features')),features:data.getAll('features')};render();persist();});
document.getElementById('sample').onclick=()=>{if([state.name,state.goal,state.audience,state.success,state.notes].some(x=>x.trim())&&!confirm('Thay bản nháp hiện tại bằng brief mẫu?'))return;state=structuredClone(sample);setForm();persist();};
document.getElementById('reset').onclick=()=>{if(!confirm('Xóa bản nháp đang lưu trên thiết bị này?'))return;state=structuredClone(defaults);setForm();persist();};
document.getElementById('download').onclick=()=>{const url=URL.createObjectURL(new Blob([markdown(state)],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='avytrix-project-brief.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('export-status').textContent='Đã tạo tệp Markdown.';};
document.getElementById('copy').onclick=async()=>{try{await navigator.clipboard.writeText(markdown(state));document.getElementById('export-status').textContent='Đã sao chép brief.';}catch{document.getElementById('export-status').textContent='Không thể sao chép. Hãy dùng Tải brief .md.';}};
setForm();if(!storageOK)document.getElementById('save-status').textContent='Không thể khôi phục nháp';
